    assertNotNull(newOc);
    assertEquals(OBJECT_CLASS_AT, newOc.getAttributeType());
    assertEquals(2, newOc.size());
    assertEquals("OBJECTCLASS", newOc.getUpId());
    assertTrue(newOc.contains("person", "inetOrgPerson"));
}

