@Test
public void testEmptyCursor() throws Exception {
    ArrayTree<Integer> tree = new ArrayTree<Integer>(new IntegerComparator());
    ArrayTreeCursor<Integer> cursor = new ArrayTreeCursor<Integer>(tree);
    assertFalse(cursor.isClosed());
    assertFalse(cursor.available());
    try {
        cursor.get();
        fail("Should not get here");
    } catch (InvalidCursorPositionException e) {
        assertNotNull(e);
    }
    cursor.beforeFirst();
    assertFalse(cursor.available());
    cursor.afterLast();
    assertFalse(cursor.available());
    assertFalse(cursor.first());
    assertFalse(cursor.available());
    assertFalse(cursor.last());
    assertFalse(cursor.available());
    assertFalse(cursor.next());
    assertFalse(cursor.available());
    assertFalse(cursor.previous());
    assertFalse(cursor.available());
    cursor.before(3);
    assertFalse(cursor.available());
    cursor.after(3);
    assertFalse(cursor.available());
    cursor.close();
    assertTrue(cursor.isClosed());
}

@Test
public void testOneEntryCursor() throws Exception {
    ArrayTree<Integer> tree = new ArrayTree<Integer>(new IntegerComparator());
    tree.insert(7);
    ArrayTreeCursor<Integer> cursor = new ArrayTreeCursor<Integer>(tree);
    assertFalse(cursor.isClosed());
    assertFalse(cursor.available());
    try {
        cursor.get();
        fail("Should not get here");
    } catch (InvalidCursorPositionException e) {
        assertNotNull(e);
    }
    cursor.beforeFirst();
    assertFalse(cursor.available());
    assertFalse(cursor.previous());
    assertTrue(cursor.next());
    assertTrue(cursor.available());
    assertEquals(7, (int) cursor.get());
    cursor.afterLast();
    assertFalse(cursor.next());
    assertFalse(cursor.available());
    assertTrue(cursor.first());
    assertTrue(cursor.available());
    assertTrue(cursor.last());
    assertTrue(cursor.available());
    assertFalse(cursor.next());
    assertFalse(cursor.available());
    assertTrue(cursor.previous());
    assertTrue(cursor.available());
    cursor.before(3);
    assertFalse(cursor.available());
    assertTrue(cursor.next());
    assertTrue(cursor.available());
    assertEquals(7, (int) cursor.get());
    cursor.before(3);
    assertFalse(cursor.previous());
    assertFalse(cursor.available());
    cursor.after(3);
    assertFalse(cursor.available());
    assertTrue(cursor.next());
    assertTrue(cursor.available());
    assertEquals(7, (int) cursor.get());
    cursor.after(3);
    assertFalse(cursor.previous());
    assertFalse(cursor.available());
    cursor.before(7);
    assertFalse(cursor.available());
    assertTrue(cursor.next());
    assertTrue(cursor.available());
    assertEquals(7, (int) cursor.get());
    cursor.before(7);
    assertFalse(cursor.previous());
    assertFalse(cursor.available());
    cursor.after(7);
    assertFalse(cursor.available());
    assertFalse(cursor.next());
    assertFalse(cursor.available());
    cursor.after(7);
    assertTrue(cursor.previous());
    assertTrue(cursor.available());
    assertEquals(7, (int) cursor.get());
    cursor.before(9);
    assertFalse(cursor.available());
    assertFalse(cursor.next());
    assertFalse(cursor.available());
    cursor.before(9);
    assertTrue(cursor.previous());
    assertTrue(cursor.available());
    assertEquals(7, (int) cursor.get());
    cursor.close();
}

