@Test
public void testRemove() {
    AvlTreeMap<Integer, Integer> tree = createTree();
    tree.insert(3, 3);
    tree.insert(2, 2);
    tree.insert(1, 1);
    tree.remove(2, 2);
    assertEquals("1,3", getInorderForm(tree));
    tree.remove(1, 1);
    assertEquals("3", getInorderForm(tree));
    assertTrue(3 == tree.getRoot().key);
    // key not present
    assertNull(tree.remove(777, 0));
    assertTrue(3 == tree.remove(3, 3));
    assertTrue(tree.isEmpty());
    tree.insert(37, 37);
    tree.insert(39, 39);
    tree.insert(27, 27);
    tree.insert(38, 38);
    tree.insert(21, 21);
    tree.insert(26, 26);
    tree.insert(43, 43);
    assertEquals("21,26,27,37,38,39,43", getInorderForm(tree));
    // remove a non-root non-leaf node in the left sub tree of root
    tree.remove(26, 26);
    assertEquals("21,27,37,38,39,43", getInorderForm(tree));
    tree.remove(43, 43);
    assertEquals("21,27,37,38,39", getInorderForm(tree));
    tree.remove(39, 39);
    assertEquals("21,27,37,38", getInorderForm(tree));
    // check the root value
    assertTrue(37 == tree.getRoot().key);
    // a double right rotation has to happen after this
    tree.remove(38, 38);
    // check the root value after double right rotation
    assertTrue(27 == tree.getRoot().key);
    assertEquals("21,27,37", getInorderForm(tree));
    if (LOG.isDebugEnabled()) {
    }
}

@Test
public void testRemoveWithDuplicateKeys() {
    AvlTreeMap<Integer, Integer> tree = createTree();
    tree.insert(1, 1);
    // insert duplicates
    tree.insert(3, 3);
    tree.insert(3, 2);
    tree.insert(3, 1);
    tree.insert(2, 3);
    tree.remove(2, 3);
    assertEquals("1,3", getInorderForm(tree));
    assertEquals(2, tree.getSize());
    tree.remove(3, 3);
    // removing a duplicate key,value shouldn't change the size
    assertEquals("1,3", getInorderForm(tree));
    assertEquals(2, tree.getSize());
    tree.remove(3, 3);
    assertEquals("1,3", getInorderForm(tree));
    assertEquals(2, tree.getSize());
    // add some more
    tree.insert(3, 3);
    tree.insert(3, 4);
    assertEquals(2, tree.getSize());
    tree.remove(3, 3);
    assertEquals("1,3", getInorderForm(tree));
    assertEquals(2, tree.getSize());
    tree.remove(3, 2);
    tree.remove(3, 1);
    // is the last value in the dupsTree should remove the whole
    tree.remove(3, 4);
    // node with key 3
    assertEquals(1, tree.getSize());
}

