/**
 * For <a href="https://issues.apache.org/jira/browse/DIRSERVER-904">DIRSERVER-904</a>.
 *
 * @throws NamingException on error
 */
@Test
public void testAddingTwoDifferentEntitiesWithSameOid() throws Exception {
    String numberOfGunsAttrLdif = "dn: m-oid=1.3.6.1.4.1.18060.0.4.1.2.999,ou=attributeTypes,cn=other,ou=schema
" + "m-usage: USER_APPLICATIONS
" + "m-equality: integerOrderingMatch
" + "objectClass: metaAttributeType
" + "objectClass: metaTop
" + "objectClass: top
" + "m-name: numberOfGuns
" + "m-oid: 1.3.6.1.4.1.18060.0.4.1.2.999
" + "m-singleValue: TRUE
" + "m-description: Number of guns of a ship
" + "m-collective: FALSE
" + "m-obsolete: FALSE
" + "m-noUserModification: FALSE
" + "m-syntax: 1.3.6.1.4.1.1466.115.121.1.27
";
    String shipOCLdif = "dn: m-oid=1.3.6.1.4.1.18060.0.4.1.2.999,ou=objectClasses,cn=other,ou=schema
" + "objectClass: top
" + "objectClass: metaTop
" + "objectClass: metaObjectclass
" + "m-supObjectClass: top
" + "m-oid: 1.3.6.1.4.1.18060.0.4.1.2.999
" + "m-name: ship
" + "m-must: cn
" + "m-may: numberOfGuns
" + "m-may: description
" + "m-typeObjectClass: STRUCTURAL
" + "m-obsolete: FALSE
" + "m-description: A ship
";
    StringReader in = new StringReader(numberOfGunsAttrLdif + "

" + shipOCLdif);
    LdifReader ldifReader = new LdifReader(in);
    LdifEntry numberOfGunsAttrEntry = ldifReader.next();
    LdifEntry shipOCEntry = ldifReader.next();
    assertFalse(ldifReader.hasNext());
    ldifReader.close();
    // should be fine with unique OID
    getService().getAdminSession().add(new DefaultEntry(getService().getSchemaManager(), numberOfGunsAttrEntry.getEntry()));
    // should blow chuncks using same OID
    try {
        getService().getAdminSession().add(new DefaultEntry(getService().getSchemaManager(), shipOCEntry.getEntry()));
        fail("Should not be possible to create two schema entities with the same OID.");
    } catch (LdapOtherException e) {
        assertTrue(true);
    }
}

