    assertNotNull(collectiveAttributeSubentries);
    //----------------------------------------------------------------------
    Attribute attr = new BasicAttribute("sn", "changedSn");
    ModificationItem mod = new ModificationItem(DirContext.REPLACE_ATTRIBUTE, attr);
