/**
 * Add a subentry under AP-A.
 * The following entries must be modified :
 * A1
 *   A1-1
 *   A1-2
 * A2
 *   A2-1
 *   AP-B
 *     B1
 *     B2
 * The following entries must not be be modified :
 * AP-A
 * not-AP
 *   C
 *
 * Then add a subentry under AP-B
 * The following entries must be modified :
 *   AP-B
 *     B1
 *     B2
 *
 * Then suppress the subentry under AP-B
 */
@Test
@Ignore
public void testSubentryAdd() throws Exception {
    LdapConnection connection = IntegrationUtils.getAdminConnection(getService());
    // Add the subentry
    Entry subEntryA = new DefaultEntry("cn=testsubentryA,dc=AP-A,dc=test,ou=system", "objectClass: top", "objectClass: subentry", "objectClass: collectiveAttributeSubentry", // All the entry from the AP, including the AP
    "subtreeSpecification: {}", "c-o: Test Org", "cn: testsubentryA");
    connection.add(subEntryA);
    assertTrue(connection.exists("cn=testsubentryA,dc=AP-A,dc=test,ou=system"));
    // Check the resulting modifications
    Map<String, Entry> results = getAllEntries(connection, "dc=test,ou=system");
    // --------------------------------------------------------------------
    // Make sure entries selected by the subentryA do have the mark
    // --------------------------------------------------------------------
    String subEntryAPADn = "2.5.4.3=testsubentrya,0.9.2342.19200300.100.1.25=ap-a,0.9.2342.19200300.100.1.25=test,2.5.4.11=system";
    String[] modifiedEntriesA = new String[] { "dc=AP-A,dc=test,ou=system", "cn=A1,dc=AP-A,dc=test,ou=system", "cn=A1-1,cn=A1,dc=AP-A,dc=test,ou=system", "cn=A1-2,cn=A1,dc=AP-A,dc=test,ou=system", "cn=A2,dc=AP-A,dc=test,ou=system", "cn=A2-1,cn=A2,dc=AP-A,dc=test,ou=system", "dc=AP-B,cn=A2,dc=AP-A,dc=test,ou=system", "cn=B1,dc=AP-B,cn=A2,dc=AP-A,dc=test,ou=system", "cn=B2,dc=AP-B,cn=A2,dc=AP-A,dc=test,ou=system" };
    for (String dn : modifiedEntriesA) {
        checkHasOpAttr(results.get(dn), "collectiveAttributeSubentries", 1, subEntryAPADn);
    }
    // --------------------------------------------------------------------
    // Make sure entries not selected by subentryA do not have the mark
    // --------------------------------------------------------------------
    String[] unchangedEntriesA = new String[] { "dc=test,ou=system", "dc=not-AP,dc=test,ou=system", "cn=C,dc=not-AP,dc=test,ou=system" };
    for (String dn : unchangedEntriesA) {
        checkDoesNotHaveOpAttr(results.get(dn), "collectiveAttributeSubentries");
    }
    // Now add another subentry on AP-B
    // Add the subentry
    Entry subEntryB = new DefaultEntry("cn=testsubentryB,dc=AP-B,cn=A2,dc=AP-A,dc=test,ou=system", "objectClass: top", "objectClass: subentry", "objectClass: collectiveAttributeSubentry", // All the entry from the AP, including the AP
    "subtreeSpecification: {}", "c-o: Test Org", "cn: testsubentryB");
    connection.add(subEntryB);
    assertTrue(connection.exists("cn=testsubentryB,dc=AP-B,cn=A2,dc=AP-A,dc=test,ou=system"));
    // Check the resulting modifications
    results = getAllEntries(connection, "dc=test,ou=system");
    // --------------------------------------------------------------------
    // Make sure entries selected by the subentryA do have the mark for
    // the subentry A
    // --------------------------------------------------------------------
    String[] modifiedEntriesAB = new String[] { "dc=AP-A,dc=test,ou=system", "cn=A1,dc=AP-A,dc=test,ou=system", "cn=A1-1,cn=A1,dc=AP-A,dc=test,ou=system", "cn=A1-2,cn=A1,dc=AP-A,dc=test,ou=system", "cn=A2,dc=AP-A,dc=test,ou=system", "cn=A2-1,cn=A2,dc=AP-A,dc=test,ou=system" };
