@Test
public void testDescendants() throws Exception {
    Iterator<AttributeType> list = schemaManager.getAttributeTypeRegistry().descendants("name");
    Set<String> nameAttrs = new HashSet<String>();
    while (list.hasNext()) {
        AttributeType type = list.next();
        nameAttrs.add(type.getName());
    }
    // We should only have 19 AT
    String[] expectedNames = new String[] { "sn", "generationQualifier", "ou", "c", "o", "l", "c-st", "givenName", "title", "cn", "initials", "dmdName", "c-ou", "c-o", "apachePresence", "st", "c-l", "ads-serverId", "ads-indexAttributeId", "ads-transportId", "ads-directoryServiceId", "ads-Id", "ads-extendedOpId", "ads-pwdId", "ads-compositeElement", "ads-replConsumerId", "ads-journalId", "ads-changeLogId", "ads-replProviderId" };
    for (String name : expectedNames) {
        if (nameAttrs.contains(name)) {
            nameAttrs.remove(name);
        }
    }
    assertEquals(0, nameAttrs.size());
}

