    Checksum checksum = chkContainer.getChecksum();
    assertEquals(ChecksumType.getTypeByValue(2), checksum.getChecksumType());
    assertTrue(Arrays.equals(Strings.getBytesUtf8("chksum"), checksum.getChecksumValue()));
