    TicketFlags flags = new TicketFlags();
    assertFalse(flags.isForwardable());
    flags.setFlag(TicketFlag.FORWARDABLE);
    assertTrue(flags.isForwardable());
    assertTrue(flags.toString().startsWith(TicketFlag.FORWARDABLE.toString()));
    assertFalse(flags.isRenewable());
    flags.setFlag(TicketFlag.RENEWABLE);
    assertTrue(flags.isRenewable());
    assertTrue(flags.isForwardable());
    int flagValue = flags.getIntValue();
    assertEquals(0x40800000, flagValue);
    flags.clearFlag(TicketFlag.FORWARDABLE);
    assertTrue(flags.isRenewable());
    assertFalse(flags.isForwardable());
    byte[] bytes = flags.getData();
    assertTrue(Arrays.equals(new byte[] { 0x00, 0x00, (byte) 0x80, 0x00, 0x00 }, bytes));
}

/**
 * Test the decoding of a full HostAddress
 */
@Test
public void testHostAddress() {
    ByteBuffer stream = ByteBuffer.allocate(0x16);
    stream.put(new byte[] { 0x30, 0x14, // addr-type
    (byte) 0xA0, // addr-type
    0x03, 0x02, 0x01, // IPV4
    0x02, (byte) 0xA1, // address : 192.168.0.1
    0x0D, 0x04, 0x0B, '1', '9', '2', '.', '1', '6', '8', '.', '0', '.', '1' });
    String decodedPdu = Strings.dumpBytes(stream.array());
    stream.flip();
    // Allocate a HostAddress Container
    Asn1Container hostAddressContainer = new HostAddressContainer();
    // Decode the HostAddress PDU
    try {
        Asn1Decoder.decode(stream, hostAddressContainer);
    } catch (DecoderException de) {
        fail(de.getMessage());
    }
    // Check the decoded HostAddress
    HostAddress hostAddress = ((HostAddressContainer) hostAddressContainer).getHostAddress();
    assertEquals(HostAddrType.ADDRTYPE_INET, hostAddress.getAddrType());
    assertTrue(Arrays.equals(Strings.getBytesUtf8("192.168.0.1"), hostAddress.getAddress()));
    // Check the encoding
    ByteBuffer bb = ByteBuffer.allocate(hostAddress.computeLength());
    try {
        bb = hostAddress.encode(bb);
        // Check the length
        assertEquals(0x16, bb.limit());
        String encodedPdu = Strings.dumpBytes(bb.array());
        assertEquals(encodedPdu, decodedPdu);
    } catch (EncoderException ee) {
        fail();
    }
}

