    int streamLen = 0x8F;
    ByteBuffer stream = ByteBuffer.allocate(streamLen);
    stream.put(new byte[] { 0x7E, (byte) 0x81, (byte) 0x8C, 0x30, (byte) 0x81, (byte) 0x89, // pvno
    (byte) 0xA0, // pvno
    0x03, 0x02, 0x01, 0x05, (byte) 0xA1, // msg-type
    0x03, 0x02, 0x01, 0x1E, (byte) 0xA2, // ctime
    0x11, 0x18, 0xF, '2', '0', '1', '0', '1', '1', '1', '9', '0', '8', '0', '0', '4', '3', 'Z', (byte) 0xA3, // cusec
    0x03, 0x02, 0x01, 0x01, (byte) 0xA4, // stime
    0x11, 0x18, 0xF, '2', '0', '1', '0', '1', '1', '1', '9', '0', '8', '0', '0', '4', '3', 'Z', (byte) 0xA5, // susec
    0x03, 0x02, 0x01, 0x02, (byte) 0xA6, // error-code
    0x03, 0x02, 0x01, 0x00, (byte) 0xA7, // crealm
    0x08, 0x1B, 0x06, 'c', 'r', 'e', 'a', 'l', 'm', (byte) 0xA8, // cname
    0x12, 0x30, 0x10, (byte) 0xA0, 0x03, 0x02, 0x01, 0x00, (byte) 0xA1, 0x09, 0x30, 0x07, 0x1B, 0x05, 'c', 'n', 'a', 'm', 'e', (byte) 0xA9, // realm
    0x07, 0x1B, 0x05, 'r', 'e', 'a', 'l', 'm', (byte) 0xAA, // sname
