    SingleFileLdifPartition partition = injectEntries();
    Dn childDn1 = new Dn(schemaManager, "cn=child1,ou=test,ou=system");
    Dn childDn2 = new Dn(schemaManager, "cn=child2,ou=test,ou=system");
