@Test
public void testCursors() throws Exception {
    initIndex();
    ParentIdAndRdn key = new ParentIdAndRdn(Strings.getUUID(0L), new Rdn("cn=key"));
    assertEquals(0, idx.count(partitionTxn));
    idx.add(partitionTxn, key, Strings.getUUID(0L));
    assertEquals(1, idx.count(partitionTxn));
    for (long i = 1; i < 5; i++) {
        key = new ParentIdAndRdn(Strings.getUUID(i), new Rdn("cn=key" + i));
        idx.add(partitionTxn, key, Strings.getUUID(i));
    }
    assertEquals(5, idx.count(partitionTxn));
    // use forward index's cursor
    Cursor<IndexEntry<ParentIdAndRdn, String>> cursor = idx.forwardCursor(partitionTxn);
    cursor.beforeFirst();
    cursor.next();
    IndexEntry<ParentIdAndRdn, String> e1 = cursor.get();
    assertEquals(Strings.getUUID(0L), e1.getId());
    assertEquals("cn=key", e1.getKey().getRdns()[0].getName());
    assertEquals(Strings.getUUID(0L), e1.getKey().getParentId());
    cursor.next();
    IndexEntry<ParentIdAndRdn, String> e2 = cursor.get();
    assertEquals(Strings.getUUID(1L), e2.getId());
    assertEquals("cn=key1", e2.getKey().getRdns()[0].getName());
    assertEquals(Strings.getUUID(1L), e2.getKey().getParentId());
    cursor.next();
    IndexEntry<ParentIdAndRdn, String> e3 = cursor.get();
    assertEquals(Strings.getUUID(2L), e3.getId());
    assertEquals("cn=key2", e3.getKey().getRdns()[0].getName());
    assertEquals(Strings.getUUID(2), e3.getKey().getParentId());
    // test before(Tuple<>)
    cursor.before(e3);
    // e3
    assertTrue(cursor.next());
    assertEquals(e3.getId(), cursor.get().getId());
    // e4
    assertTrue(cursor.next());
    assertEquals(Strings.getUUID(3), cursor.get().getId());
    // e5
    assertTrue(cursor.next());
    assertEquals(Strings.getUUID(4), cursor.get().getId());
    assertFalse(cursor.next());
    cursor.close();
}

/**
 * Tests a suffix with two name components: dc=example,dc=com.
 * When reading this entry back from the store the Dn must
 * consist of two RDNs.
 */
@Test
public void testTwoComponentSuffix() throws Exception {
    // setup the working directory for the 2nd store
    File wkdir2 = tmpDir.newFolder(getClass().getSimpleName() + "-store2");
    // initialize the 2nd store
    MavibotPartition store2 = new MavibotPartition(schemaManager, dnFactory);
    store2.setId("example2");
    store2.setCacheSize(10);
    store2.setPartitionPath(wkdir2.toURI());
    store2.setSyncOnWrite(false);
    store2.addIndex(new MavibotIndex(SchemaConstants.OU_AT_OID, false));
    store2.addIndex(new MavibotIndex(SchemaConstants.UID_AT_OID, false));
    store2.setSuffixDn(EXAMPLE_COM);
    store2.initialize();
    // inject context entry
    Dn suffixDn = new Dn(schemaManager, "dc=example,dc=com");
    Entry entry = new DefaultEntry(schemaManager, suffixDn, "objectClass: top", "objectClass: domain", "dc: example", SchemaConstants.ENTRY_CSN_AT, new CsnFactory(0).newInstance().toString(), SchemaConstants.ENTRY_UUID_AT, UUID.randomUUID().toString());
    AddOperationContext addContext = new AddOperationContext(null, entry);
    addContext.setPartition(store2);
    addContext.setTransaction(store2.beginWriteTransaction());
    store2.add(addContext);
    // lookup the context entry
    String id = store2.getEntryId(partitionTxn, suffixDn);
    Entry lookup = store2.fetch(partitionTxn, id, suffixDn);
    assertEquals(2, lookup.getDn().size());
    // make sure all files are closed so that they can be deleted on Windows.
    // wkdir2 is deleted by TemporaryFolder rule
}

