@Test
public void testAddIAP() throws Exception {
    assertTrue(getLdapServer().isStarted());
    // First check that we can't add an IAP in the DIT if there is no
    // parent AAP or SAP with the same role
    Entry entry = new DefaultEntry("ou=IAP-CANew,ou=entry,ou=system", "ObjectClass: top", "ObjectClass: organizationalUnit", "ou: IAP-CANew", "administrativeRole: collectiveAttributeInnerArea");
    try {
        connection.add(entry);
        fail();
    } catch (LdapUnwillingToPerformException lutpe) {
        assertTrue(true);
    }
    // Add the entry under a SAP with the same role which has no parent AAP
    entry = new DefaultEntry("ou=IAP-CANew,ou=SAP-CA2,ou=system", "ObjectClass: top", "ObjectClass: organizationalUnit", "ou: IAP-CANew", "administrativeRole: collectiveAttributeInnerArea");
    connection.add(entry);
