    entry = new DefaultEntry("ou=IAP-CANew,ou=SAP-AC2,ou=system", "ObjectClass: top", "ObjectClass: organizationalUnit", "ou: IAP-CANew", "administrativeRole: collectiveAttributeInnerArea");
    try {
        connection.add(entry);
        fail();
