    }
    // Add the entry under an AAP
    entry = new DefaultEntry("ou=IAP-CANew,ou=AAP1,ou=system", "ObjectClass: top", "ObjectClass: organizationalUnit", "ou: IAP-CANew", "administrativeRole: collectiveAttributeInnerArea");
    connection.add(entry);
