    // Add the entry under an IAP with the same role which has a parent AAP
    entry = new DefaultEntry("ou=IAP-CANew,ou=IAP-CA1,ou=AAP1,ou=system", "ObjectClass: top", "ObjectClass: organizationalUnit", "ou: IAP-CANew", "administrativeRole: collectiveAttributeInnerArea");
    connection.add(entry);
    // It should succeed
    assertTrue(connection.exists("ou=IAP-CANew,ou=IAP-CA1,ou=AAP1,ou=system"));
    // Add the entry under an IAP with a different role which has a parent AAP
    entry = new DefaultEntry("ou=IAP-CANew,ou=IAP-AC1,ou=AAP1,ou=system", "ObjectClass: top", "ObjectClass: organizationalUnit", "ou: IAP-CANew", "administrativeRole: collectiveAttributeInnerArea");
    connection.add(entry);
    // It should succeed
    assertTrue(connection.exists("ou=IAP-CANew,ou=IAP-AC1,ou=AAP1,ou=system"));
    // Add the entry under an SAP with the same role which has a parent AAP
    entry = new DefaultEntry("ou=IAP-CANew,ou=SAP-CA1,ou=AAP1,ou=system", "ObjectClass: top", "ObjectClass: organizationalUnit", "ou: IAP-CANew", "administrativeRole: collectiveAttributeInnerArea");
    connection.add(entry);
    // It should succeed
    assertTrue(connection.exists("ou=IAP-CANew,ou=SAP-CA1,ou=AAP1,ou=system"));
    // Add the entry under an SAP with a different role which has a parent AAP
    entry = new DefaultEntry("ou=IAP-CANew,ou=SAP-AC1,ou=AAP1,ou=system", "ObjectClass: top", "ObjectClass: organizationalUnit", "ou: IAP-CANew", "administrativeRole: collectiveAttributeInnerArea");
