@Test
public void testModifyAddWithNullValues() throws LdapException, IOException {
    LdapConnection connection = new LdapNetworkConnection(Network.LOOPBACK_HOSTNAME, getLdapServer().getPort());
    // Use the client API
    connection.bind("uid=admin,ou=system", "secret");
    // Add a new entry with some null values
    Entry entry = new DefaultEntry("uid=12345,ou=system", "ObjectClass: top", "ObjectClass: person", "ObjectClass: person", "ObjectClass: OrganizationalPerson", "ObjectClass: inetOrgPerson", "uid: 12345", "cn: test", "sn: Test", "userPassword: 12345");
    connection.add(entry);
    // Now modify the entry : we should add two null values
    connection.modify(new Dn("uid=12345,ou=system"), new DefaultModification(ModificationOperation.ADD_ATTRIBUTE, "userPassword", Strings.EMPTY_BYTES), new DefaultModification(ModificationOperation.ADD_ATTRIBUTE, "mail", (String) null));
    // Get back the entry
    Entry found = connection.lookup("uid=12345,ou=system");
    assertNotNull(found);
    assertNotNull(found.get("mail"));
