            for (; i < 100; i++) {
                rename(connection, base, oldDn, oldUid, oldCn, newRdn, newUid, newDn);
            }
        } catch (LdapException le) {
            System.out.println("Error at loop " + i);
            try {
                rename(connection, base, oldDn, oldUid, oldCn, newRdn, newUid, newDn);
            } catch (LdapException le2) {
                le.printStackTrace();
            }
        }
    }
}

