@Test
public void testSortByDn() throws Exception {
    sk.setAttributeTypeDesc("entryDn");
    sk.setMatchingRuleId(SchemaConstants.DISTINGUISHED_NAME_MATCH_MR_OID);
    SearchCursor cursor = con.search(req);
    List<Entry> actualOrder = new ArrayList<Entry>();
    while (cursor.next()) {
        SearchResultEntry se = (SearchResultEntry) cursor.get();
        Entry entry = se.getEntry();
        actualOrder.add(entry);
    }
    cursor.close();
    // start deleting from the first entry
    // SHOULD succeeded if the order is as expected
    for (int i = 0; i < actualOrder.size(); i++) {
        con.delete(actualOrder.get(i).getDn());
    }
    // now insert from the last entry, SHOULD succeed
    for (int i = actualOrder.size() - 1; i >= 0; i--) {
        con.add(actualOrder.get(i));
    }
    actualOrder.clear();
    sk.setReverseOrder(true);
    cursor = con.search(req);
    while (cursor.next()) {
        SearchResultEntry se = (SearchResultEntry) cursor.get();
        Entry entry = se.getEntry();
        actualOrder.add(entry);
    }
    // now delete again, this time from the end, SHOULD succeed
    for (int i = actualOrder.size() - 1; i >= 0; i--) {
        con.delete(actualOrder.get(i).getDn());
    }
    // now insert again, but from the beginning, SHOULD succeed
    for (int i = 0; i < actualOrder.size(); i++) {
        con.add(actualOrder.get(i));
    }
}

/**
 * Verifies that the admin user is exempt from pwdHistory checks.
 *
 * <a href="https://issues.apache.org/jira/browse/DIRSERVER-2084">DIRSERVER-
 * 2084</>
 */
@Test
public void testAdminExemptPwdHistory() throws Exception {
    String user = "adminexemptpwdhistory";
    String password = "12345";
    try (LdapConnection adminConnection = getAdminNetworkConnection(getLdapServer())) {
        policyConfig.setPwdCheckQuality(CheckQualityEnum.CHECK_ACCEPT);
        Entry userEntry = adminConnection.lookup(addUser(adminConnection, user, password), "*", "+");
        Dn userDn = userEntry.getDn();
        ModifyResponse response = changePassword(userDn, password, password);
        assertEquals(ResultCodeEnum.CONSTRAINT_VIOLATION, response.getLdapResult().getResultCode());
        PasswordPolicyResponse respCtrl = getPwdRespCtrl(response);
        assertNotNull(respCtrl);
        assertEquals(PasswordPolicyErrorEnum.PASSWORD_IN_HISTORY, respCtrl.getPasswordPolicyError());
