@Test
public void testCursorWithKey() throws Exception {
    injectNoDupsData(txn, nodups);
    Cursor<Tuple<Integer, Integer>> cursor = nodups.cursor(txn, 2);
    cursor.beforeFirst();
    assertFalse(cursor.available());
    assertTrue(cursor.next());
