    cursor.beforeFirst();
    assertFalse(cursor.available());
    assertTrue(cursor.next());
    assertTrue(cursor.available());
    assertEquals(SchemaConstants.SN_AT_OID, cursor.get().getKey());
    // test afterLast()
    set.clear();
    cursor.afterLast();
    assertFalse(cursor.available());
    while (cursor.previous()) {
